#include <stdio.h>
#include <string.h>

typedef struct { int id; char desc[64]; } Task;

Task tasks[5] = {{1,"Process data"},{2,"Send email"},{3,"Generate report"},{4,"Backup files"},{5,"Clean cache"}};
int next_task = 0;

int worker_get_task() {
    if (next_task < 5) return next_task++;
    return -1;
}

void worker_run(int worker_id) {
    while (1) {
        int t = worker_get_task();
        if (t == -1) break;
        printf("Worker %d processing: %s\n", worker_id, tasks[t].desc);
    }
}

int main() {
    for (int w = 1; w <= 3; w++) worker_run(w);
    return 0;
}
